 "content": "from collections import deque


def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    components = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                rr, cc = q.popleft()
                cells.append((rr, cc))
                for nr, nc in ((rr-1, cc), (rr+1, cc), (rr, cc-1), (rr, cc+1)):
                    if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] != 0 and (nr, nc) not in seen:
                        seen.add((nr, nc))
                        q.append((nr, nc))
            components.append(cells)
    panel = max(components, key=len)
    r0 = min(r for r, c in panel)
    r1 = max(r for r, c in panel)
    c0 = min(c for r, c in panel)
    c1 = max(c for r, c in panel)
    height, width = r1-r0+1, c1-c0+1
    out = [[0] * height for _ in range(width)]
    for r in range(height):
        for c in range(width):
            out[width-1-c][height-1-r] = grid[r0+r][c0+c]
    return out
